_PLATFORM_CONFIG: dict[str, dict] = {
    "windows-x86_64": {
        "pip_platform_tags": ("win_amd64",),
    },
    "linux-x86_64": {
        "max_glibc": (2, 28),
        "arch": "x86_64",
