            machine = struct.unpack_from("<H", pe_header, 4)[0]
            return {0x8664: "x86_64", 0xAA64: "aarch64"}.get(machine)

    # Mach-O 64-bit
    magic = struct.unpack_from("<I", header, 0)[0]
    if magic == 0xFEEDFACF:  # little-endian
